<script setup>
import CampusLayout from '../../Layouts/MarketplaceLayout.vue';
import { Link, useForm } from '@inertiajs/vue3';
defineProps({ returns:Object, isAdmin:Boolean, canResolveIds:Array });
const form = useForm({ decision:'approved', resolution_notes:'' });
function resolve(id,decision) { form.decision=decision; form.post(`/tienda/postventa/${id}/resolver`, {preserveScroll:true}); }
</script>
<template><CampusLayout title="Postventa"><div class="max-w-[1180px] mx-auto space-y-5"><div class="flex justify-between items-end"><div><p class="text-xs text-campus-blue">3.10 · POSTVENTA</p><h1 class="text-2xl font-bold">Solicitudes de devolución</h1><p class="text-sm text-slate-500">Las decisiones quedan auditadas. El reembolso externo requiere el contrato del Equipo 2.</p></div><Link href="/tienda/pedidos" class="text-sm text-campus-blue">← Mis pedidos</Link></div><div class="bg-white border rounded-xl divide-y"><div v-for="r in returns.data" :key="r.id" class="p-5"><div class="flex justify-between gap-3"><div><h2 class="font-bold">Solicitud {{ r.id }}</h2><p class="text-sm text-slate-500">Pedido: {{ r.order_id }} · Negocio: {{ r.business_id }}</p><p class="mt-2 text-sm">{{ r.reason }}</p><p v-if="r.resolution_notes" class="text-xs text-slate-500 mt-2">Resolución: {{ r.resolution_notes }}</p></div><span class="text-xs rounded-full bg-slate-100 px-3 py-1 h-fit">{{ r.status }}</span></div><div v-if="!isAdmin && r.status==='pending'" class="mt-3 text-xs text-slate-500">Pendiente de resolución por el negocio.</div><div v-if="canResolveIds?.includes(r.id) && r.status==='pending'" class="mt-3 space-y-2"><textarea v-model="form.resolution_notes" required placeholder="Motivo de la resolución" class="w-full rounded border p-2 text-sm"></textarea><div class="flex gap-2"><button @click="resolve(r.id,'approved')" class="rounded bg-green-700 text-white px-3 py-2 text-xs">Aprobar devolución</button><button @click="resolve(r.id,'rejected')" class="rounded bg-red-600 text-white px-3 py-2 text-xs">Rechazar</button></div></div></div><div v-if="!returns.data?.length" class="p-10 text-center text-slate-400">No hay solicitudes.</div></div></div></CampusLayout></template>
